            <tr><td className="px-3 py-2 text-xs">長野県</td><td className="px-3 py-2 text-xs">塩尻市</td><td className="px-3 py-2 text-xs">住宅近く</td><td className="px-3 py-2 text-xs">1頭捕獲（※22）</td></tr>
